F=np.load('feats.npz'); y=F['y']; folds=np.load('folds.npy')
A={}
for L in [7,8,9,10,11]:
    A[f'C{L}']=np.concatenate([np.load(f'pass_8/cls_hidden_L{L}.npy'),np.load(f'pass_9/cls_hidden_L{L}.npy')])
    A[f'M{L}']=np.concatenate([np.load(f'pass_8/mean_hidden_L{L}.npy'),np.load(f'pass_9/mean_hidden_L{L}.npy')])
np.savez('featsA.npz',**A)
def stdz(X,tr): mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; return (X-mu)/sd
def cv(featfn, lam):
    accs=[]
    for f in range(5):
        tr=folds!=f; te=~tr
        Z=featfn(tr); mu=Z[tr].mean(0); Zc=Z-mu
        Y=np.eye(8)[y[tr]]-1/8
        K=Zc@Zc[tr].T; a=np.linalg.solve(K[tr]+lam*np.eye(tr.sum()),Y); pr=K[te]@a
        accs.append((np.argmax(pr,1)==y[te]).mean())
    return round(np.mean(accs),4)
for L in [7,9,11]:
    dM=np.linalg.norm(A[f'M{L}']-F[f'M{L}'],axis=1).mean()/np.linalg.norm(F[f'M{L}']-F[f'M{L}'].mean(0),axis=1).mean()
    dC=np.linalg.norm(A[f'C{L}']-F[f'C{L}'],axis=1).mean()/np.linalg.norm(F[f'C{L}']-F[f'C{L}'].mean(0),axis=1).mean()
    print(L,'rel change mean-feat %.3f  cls %.3f'%(dM,dC))
for k in ['C7','C9','C11','M11']:
    print('edited',k,[cv(lambda tr: stdz(A[k],tr),l) for l in [30,100,300]], ' base',[cv(lambda tr: stdz(F[k],tr),l) for l in [30,100,300]])
for wc in [0.7,1.0]:
    fn=lambda tr: np.concatenate([wc*stdz(A['C11'],tr),stdz(A['M11'],tr)],1)
    print('edited C11+M11 wc',wc,[cv(fn,l) for l in [100,200,300,500]])
